type Span struct {
	Kind   Kind           `json:"kind"`
	Text   string         `json:"text"`
	Action string         `json:"action,omitempty"`
	Kwargs map[string]any `json:"kwargs,omitempty"`
}

type Adopter interface {
	Split(path string, src []byte) ([]Span, error)
}

type CoverageError struct {
	Offset int
	Line   int
	Want   string
	Got    string
}

func (e CoverageError) Error() string {
	return fmt.Sprintf("coverage: spans differ from the file at byte %d (line %d): want %q got %q", e.Offset, e.Line, e.Want, e.Got)
}

func Coverage(src []byte, spans []Span) error {
	var got []byte
	for _, s := range spans {
		got = append(got, s.Text...)
	}
	if string(got) == string(src) {
		return nil
	}
	off := 0
	for off < len(got) && off < len(src) && got[off] == src[off] {
		off++
	}
	line := 1
	for _, c := range src[:off] {
		if c == '\n' {
			line++
		}
	}
	end := off + 40
	if end > len(src) {
		end = len(src)
	}
	gend := off + 40
	if gend > len(got) {
		gend = len(got)
	}
	return &CoverageError{Offset: off, Line: line, Want: string(src[off:end]), Got: string(got[off:gend])}
}

func (s Span) Valid() error {
	switch s.Kind {
	case KindUnit:
		if s.Action == "" || s.Text == "" {
			return fmt.Errorf("unit span needs an action and text")
		}
	case KindHeader:
		if s.Action != "" || s.Kwargs != nil {
			return fmt.Errorf("%s span must not carry an action or kwargs", s.Kind)
		}
	case KindResidual:
		if s.Action != "" || s.Kwargs != nil {
			return fmt.Errorf("%s span must not carry an action or kwargs", s.Kind)
		}
	default:
		return fmt.Errorf("unknown span kind %q", s.Kind)
	}
	return nil
}

func CheckSpans(src []byte, spans []Span) error {
	if len(spans) == 0 && len(src) > 0 {
		return fmt.Errorf("no spans for a non-empty file")
	}
	for i, s := range spans {
		if err := s.Valid(); err != nil {
			return fmt.Errorf("span %d: %w", i, err)
		}
	}
	return Coverage(src, spans)
}

func ResidualIsBlank(s Span) bool {
	return s.Kind == KindResidual && strings.TrimSpace(s.Text) == ""
}

func TestCoverage(t *testing.T) {
	src := []byte("a\nfunc b\n")
	tests := []struct {
		name   string
		spans  []Span
		offset int
		line   int
	}{
		{"exact", []Span{{Kind: KindHeader, Text: "a\n"}, {Kind: KindUnit, Text: "func b\n"}}, -1, 0},
		{"missing byte", []Span{{Kind: KindHeader, Text: "a\n"}, {Kind: KindUnit, Text: "func \n"}}, 7, 2},
		{"extra byte", []Span{{Kind: KindHeader, Text: "a\n"}, {Kind: KindUnit, Text: "func bb\n"}}, 8, 2},
		{"changed byte", []Span{{Kind: KindHeader, Text: "a\n"}, {Kind: KindUnit, Text: "func c\n"}}, 7, 2},
		{"prefix", []Span{{Kind: KindHeader, Text: "a\nfunc "}}, 7, 2},
		{"empty spans", nil, 0, 1},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			err := Coverage(src, tc.spans)
			if tc.offset < 0 {
				if err != nil {
					t.Fatalf("unexpected error: %v", err)
				}
				return
			}
			var ce *CoverageError
			if !errors.As(err, &ce) {
				t.Fatalf("want *CoverageError, got %v", err)
			}
			if ce.Offset != tc.offset || ce.Line != tc.line {
				t.Fatalf("got offset %d line %d, want offset %d line %d", ce.Offset, ce.Line, tc.offset, tc.line)
			}
		})
	}
}

func TestValid(t *testing.T) {
	tests := []struct {
		name    string
		span    Span
		wantErr bool
	}{
		{"unit ok", Span{Kind: KindUnit, Text: "x", Action: "setFunction"}, false},
		{"unit no action", Span{Kind: KindUnit, Text: "x"}, true},
		{"unit no text", Span{Kind: KindUnit, Action: "setFunction"}, true},
		{"header ok", Span{Kind: KindHeader, Text: "x"}, false},
		{"header with action", Span{Kind: KindHeader, Text: "x", Action: "setFunction"}, true},
		{"residual with kwargs", Span{Kind: KindResidual, Text: "x", Kwargs: map[string]any{"a": 1}}, true},
		{"unknown kind", Span{Kind: "bogus", Text: "x"}, true},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			err := tc.span.Valid()
			if (err != nil) != tc.wantErr {
				t.Fatalf("Valid() error = %v, wantErr %v", err, tc.wantErr)
			}
		})
	}
}

func TestCheckSpans(t *testing.T) {
	src := []byte("a\nb\n")
	good := Span{Kind: KindHeader, Text: "a\n"}
	tests := []struct {
		name    string
		spans   []Span
		wantErr string
	}{
		{"ok", []Span{good, {Kind: KindResidual, Text: "b\n"}}, ""},
		{"empty spans", nil, "no spans"},
		{"bad span index", []Span{good, {Kind: KindUnit, Text: "b\n"}}, "span 1:"},
		{"coverage", []Span{good}, "coverage"},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			err := CheckSpans(src, tc.spans)
			if tc.wantErr == "" {
				if err != nil {
					t.Fatalf("unexpected error: %v", err)
				}
				return
			}
			if err == nil || !strings.Contains(err.Error(), tc.wantErr) {
				t.Fatalf("got error %v, want it to contain %q", err, tc.wantErr)
			}
		})
	}
}

